//! Minimal terminal size detection used by clap's `wrap_help` feature.
//!
//! Queries stdout, then stderr, then stdin for a terminal window size.

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Width(pub u16);

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Height(pub u16);

#[repr(C)]
#[derive(Default)]
struct WinSize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

extern "C" {
    fn isatty(fd: i32) -> i32;
    fn ioctl(fd: i32, request: std::os::raw::c_ulong, ...) -> i32;
}

#[cfg(any(target_os = "linux", target_os = "android"))]
const TIOCGWINSZ: std::os::raw::c_ulong = 0x5413;
#[cfg(not(any(target_os = "linux", target_os = "android")))]
const TIOCGWINSZ: std::os::raw::c_ulong = 0x40087468;

/// Returns the size of the terminal attached to the given raw file descriptor.
pub fn terminal_size_of_fd(fd: i32) -> Option<(Width, Height)> {
    unsafe {
        if isatty(fd) != 1 {
            return None;
        }
        let mut ws = WinSize::default();
        if ioctl(fd, TIOCGWINSZ, &mut ws as *mut WinSize) != 0 {
            return None;
        }
        if ws.ws_row > 0 && ws.ws_col > 0 {
            Some((Width(ws.ws_col), Height(ws.ws_row)))
        } else {
            None
        }
    }
}

/// Returns the size of the terminal, checking stdout, stderr and stdin in order.
pub fn terminal_size() -> Option<(Width, Height)> {
    terminal_size_of_fd(1)
        .or_else(|| terminal_size_of_fd(2))
        .or_else(|| terminal_size_of_fd(0))
}
EOF
