{"command":"cd /workspace; cat > src/csv.rs <<'EOF'
//! A small streaming CSV reader.
//!
//! The parser is a byte oriented state machine supporting quoted fields,
//! doubled quotes as escapes, and `\r`, `\n` or `\r\n` record terminators.
//! Empty lines are skipped. Every record must have the same number of fields
//! as the first record, and fields must be valid UTF-8.

use std::fmt;
use std::io::{self, BufRead, BufReader, Read};

const QUOTE: u8 = b'"';
const BOM: &[u8] = b"\xef\xbb\xbf";

/// Location of a record within the input.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct Position {
    /// Byte offset of the start of the record.
    pub byte: u64,
    /// 1-based line number of the start of the record.
    pub line: u64,
    /// 0-based index of the record (the header row counts as a record).
    pub record: u64,
}

/// Errors produced while reading CSV data.
#[derive(Debug)]
pub enum Error {
    Io(io::Error),
    Utf8 {
        pos: Position,
        field: usize,
        valid_up_to: usize,
    },
    UnequalLengths {
        pos: Position,
        expected_len: u64,
        len: u64,
    },
}

impl Error {
    pub fn is_broken_pipe(&self) -> bool {
        matches!(self, Error::Io(e) if e.kind() == io::ErrorKind::BrokenPipe)
    }
}

impl From<io::Error> for Error {
    fn from(err: io::Error) -> Self {
        Error::Io(err)
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::Io(err) => err.fmt(f),
            Error::Utf8 {
                pos,
                field,
                valid_up_to,
            } => write!(
                f,
                "CSV parse error: record {} (line {}, field: {}, byte: {}): \
                 invalid utf-8: invalid UTF-8 in field {} near byte index {}",
                pos.record, pos.line, field, pos.byte, field, valid_up_to
            ),
            Error::UnequalLengths {
                pos,
                expected_len,
                len,
            } => write!(
                f,
                "CSV error: record {} (line: {}, byte: {}): \
                 found record with {} fields, but the previous record has {} fields",
                pos.record, pos.line, pos.byte, len, expected_len
            ),
        }
    }
}

impl std::error::Error for Error {}

/// A record made of raw bytes.
#[derive(Debug, Clone, Default)]
pub struct ByteRecord {
    data: Vec<u8>,
    ends: Vec<usize>,
    pos: Position,
}

impl ByteRecord {
    fn clear(&mut self) {
        self.data.clear();
