//! Display width computation for terminal output.
//!
//! Widths are computed per extended grapheme cluster, so that emoji
//! sequences and combining characters are measured as a single unit.

use unicode_segmentation::UnicodeSegmentation;
use unicode_width::UnicodeWidthStr;

/// Display width of a single grapheme cluster.
#[inline]
fn grapheme_width(g: &str) -> usize {
    crate::unicode_compat::grapheme_width(g).unwrap_or_else(|| g.width())
}

/// Display width of a string.
pub fn str_width(s: &str) -> usize {
    if s.is_ascii() {
        return ascii_width(s.as_bytes());
    }
    s.graphemes(true).map(grapheme_width).sum()
}

#[inline]
fn ascii_width(bytes: &[u8]) -> usize {
    // Every ASCII character occupies one column, except that "\r\n" is
    // treated as a single unit.
    let mut w = bytes.len();
    let mut i = 1;
    while i < bytes.len() {
        if bytes[i] == b'\n' && bytes[i - 1] == b'\r' {
            w -= 1;
        }
        i += 1;
    }
    w
}

/// Returns the longest prefix of `s` (cut at a grapheme boundary) whose
/// display width does not exceed `max`, together with that width.
pub fn truncate(s: &str, max: usize) -> (&str, usize) {
    let mut width = 0usize;
    let mut end = 0usize;
    for (idx, g) in s.grapheme_indices(true) {
        if width > max {
            break;
        }
        end = idx;
        let gw = grapheme_width(g);
        if width + gw > max {
            // This grapheme does not fit; the cut is before it, unless
            // following zero width graphemes also fit (they cannot here
            // since the width already exceeds max after adding).
            return (&s[..end], width);
        }
        width += gw;
        end = idx + g.len();
    }
    (&s[..end], width)
}
