pub use row::Row;
pub use style::{LinePosition, TableFormat};

use std::io::{self, Write};

use crate::cli::Alignment;

/// Streaming table printer: column widths are fixed up-front, rows are
/// printed as they arrive.
pub struct TablePrinter<'a, W: Write> {
    wtr: W,
    format: &'a TableFormat,
    widths: Vec<usize>,
    has_header: bool,
    body_align: Alignment,
    rows_printed: usize,
}

impl<'a, W: Write> TablePrinter<'a, W> {
    pub fn new(
        wtr: W,
        format: &'a TableFormat,
        widths: Vec<usize>,
        has_header: bool,
        body_align: Alignment,
    ) -> Self {
        TablePrinter {
            wtr,
            format,
            widths,
            has_header,
            body_align,
            rows_printed: 0,
        }
    }

    /// Prints the top border and, if present, the header row.
    pub fn begin(&mut self, header: Option<&[String]>, header_align: Alignment) -> io::Result<()> {
        self.format
            .print_line_separator(&mut self.wtr, &self.widths, LinePosition::Top)?;
        if let Some(header) = header {
            Row::new(header).print(&mut self.wtr, self.format, &self.widths, header_align)?;
        }
        Ok(())
    }

    /// Prints a body row, preceded by the appropriate separator.
    pub fn row(&mut self, cells: &[String]) -> io::Result<()> {
        if self.rows_printed == 0 {
            if self.has_header {
                self.format
                    .print_line_separator(&mut self.wtr, &self.widths, LinePosition::Title)?;
            }
        } else {
            self.format
                .print_line_separator(&mut self.wtr, &self.widths, LinePosition::Intern)?;
        }
        Row::new(cells).print(&mut self.wtr, self.format, &self.widths, self.body_align)?;
        self.rows_printed += 1;
        Ok(())
    }

    /// Prints the bottom border.
    pub fn finish(&mut self) -> io::Result<()> {
        self.format
            .print_line_separator(&mut self.wtr, &self.widths, LinePosition::Bottom)?;
        self.wtr.flush()
    }

    pub fn flush(&mut self) -> io::Result<()> {
        self.wtr.flush()
    }
}
