    pub fn print<W: Write>(&self, wtr: &mut W, fmt: &TableFormat, widths: &[usize], align: Alignment) -> io::Result<()> {
        let mut buf = [0u8; 4];
        let indent = fmt.indent;
        write!(wtr, "{:indent$}", "")?;
        if let Some(c) = fmt.lborder {
            wtr.write_all(c.encode_utf8(&mut buf).as_bytes())?;
        }
        for (i, (cell, &width)) in self.cells.iter().zip(widths).enumerate() {
            let pad = fmt.padding;
            if i > 0 { if let Some(c) = fmt.csep { wtr.write_all(c.encode_utf8(&mut buf).as_bytes())?; } }
            let result = write!(wtr, "{:pad$}", "");
            result?;
            write_aligned(wtr, cell, width, align)?;
            write!(wtr, "{:pad$}", "")?;
        }
        if let Some(c) = fmt.rborder {
            wtr.write_all(c.encode_utf8(&mut buf).as_bytes())?;
        }
        wtr.write_all(b"\n")
    }
}

/// Writes `n` spaces.
fn write_spaces<W: Write>(wtr: &mut W, mut n: usize) -> io::Result<()> {
    const SPACES: &[u8; 64] = b"                                                                ";
    while n > 0 {
        let k = n.min(SPACES.len());
        wtr.write_all(&SPACES[..k])?;
        n -= k;
    }
    Ok(())
}

/// Writes `text` aligned within `width` columns, truncating it at a
/// grapheme boundary if it is too wide.
fn write_aligned<W: Write>(wtr: &mut W, text: &str, width: usize, align: Alignment) -> io::Result<()> {
    let mut text_width = str_width(text);
    let mut text = text;
    if text_width > width {
        let (prefix, w) = truncate(text, width);
        text = prefix;
        text_width = w;
    }
    let space = width - text_width;
    let (left, right) = match align {
        Alignment::Left => (0, space),
        Alignment::Right => (space, 0),
        Alignment::Center => (space / 2, space - space / 2),
    };
    write_spaces(wtr, left)?;
    wtr.write_all(text.as_bytes())?;
    write_spaces(wtr, right)
}
