use std::os::unix::ffi::{OsStrExt, OsStringExt};
use std::path::{Path, PathBuf};

const PAGER_ENV: &str = "CSVIEW_PAGER";
const DEFAULT_PAGER: &str = "less";
const DEFAULT_PAGER_ENV: (&str, &str) = ("LESS", "-SF");

extern "C" {
    fn isatty(fd: i32) -> i32;
    fn pipe(fds: *mut i32) -> i32;
    fn fork() -> i32;
    fn dup2(old: i32, new: i32) -> i32;
    fn close(fd: i32) -> i32;
    fn execvp(file: *const std::os::raw::c_char, argv: *const *const std::os::raw::c_char) -> i32;
    fn signal(signum: i32, handler: usize) -> usize;
    fn raise(sig: i32) -> i32;
    fn _exit(code: i32) -> !;
}

const SIGSEGV: i32 = 11;
const SIG_DFL: usize = 0;

/// Locates an executable in `PATH` (or checks it directly if it contains a
/// slash).
fn which(name: &OsStr) -> Option<PathBuf> {
    if name.as_bytes().contains(&b'/') {
        return Some(PathBuf::from(name));
    }
    let path = env::var_os("PATH")?;
    for dir in env::split_paths(&path) {
        let candidate = dir.join(name);
        if is_executable(&candidate) {
            return Some(candidate);
        }
    }
    None
}

fn is_executable(path: &Path) -> bool {
    use std::os::unix::fs::PermissionsExt;
    match std::fs::metadata(path) {
        Ok(meta) => meta.is_file() && meta.permissions().mode() & 0o111 != 0,
        Err(_) => false,
    }
}

/// Command line of the pager to run, and extra environment variables.
struct PagerCommand {
    args: Vec<OsString>,
    envs: Vec<(&'static str, &'static str)>,
}

fn find_pager() -> Option<PagerCommand> {
    if env::var_os("NOPAGER").is_some() {
        return None;
    }
    match env::var_os(PAGER_ENV) {
        Some(value) => {
            let args: Vec<OsString> = value
                .as_bytes()
                .split(|b| b.is_ascii_whitespace())
                .filter(|s| !s.is_empty())
                .map(|s| OsString::from_vec(s.to_vec()))
                .collect();
            if let Some(first) = args.first() {
                which(first)?;
            }
            Some(PagerCommand {
                args,
                envs: Vec::new(),
            })
        }
        None => {
            which(OsStr::new(DEFAULT_PAGER))?;
            Some(PagerCommand {
                args: vec![OsString::from(DEFAULT_PAGER)],
                envs: vec![DEFAULT_PAGER_ENV],
            })
        }
    }
}

/// Sets up the pager if standard output is a terminal.
pub fn setup() {
    if unsafe { isatty(1) } != 1 {
        return;
    }
    let pager = match find_pager() {
        Some(p) => p,
        None => return,
    };
    let argv: Vec<CString> = pager
        .args
        .iter()
        .filter_map(|a| CString::new(a.as_bytes()).ok())
        .collect();

    let mut fds = [0i32; 2];
    if unsafe { pipe(fds.as_mut_ptr()) } != 0 {
        return;
    }
    let (read_end, write_end) = (fds[0], fds[1]);
    let pid = unsafe { fork() };
    if pid < 0 {
        unsafe {
            close(read_end);
            close(write_end);
        }
        return;
    }
    if pid == 0 {
        // Child: continue running the program, writing into the pipe.
        unsafe {
            dup2(write_end, 1);
            close(read_end);
            close(write_end);
        }
        return;
    }
    // Parent: become the pager.
    unsafe {
        dup2(read_end, 0);
        close(write_end);
        close(read_end);
    }
    for (k, v) in &pager.envs {
        env::set_var(k, v);
    }
