/// Smallest code point present in [`WIDTH_OVERRIDES`].
const MIN_OVERRIDE_CP: u32 = 0x897;

/// Expected width of `c`, if it differs from the `unicode-width` tables.
#[inline]
fn override_of(c: char) -> Option<u8> {
    let cp = c as u32;
    if cp < MIN_OVERRIDE_CP {
        return None;
    }
    WIDTH_OVERRIDES
