        .map(|i| WIDTH_OVERRIDES[i].2)
}

/// Neutral characters of width 0, 1 and 2.
fn stand_in(width: u8) -> char {
    match width {
        0 => '\\u{200B}',
        1 => '\\u{0378}',
        _ => '\\u{4E00}',
    }
}

/// Returns `g` with every overridden code point replaced by a stand-in, or
/// `None` if the grapheme contains no such code point.
#[inline]
pub fn normalize_grapheme(g: &str) -> Option<String> {
    if g.chars().all(|c| override_of(c).is_none()) {
        return None;
    }
    Some(
        g.chars()
            .map(|c| match override_of(c) {
                Some(w) => stand_in(w),
                None => c,
            })
            .collect(),
    )
}
